// ========== CONFIGURATION DES ÉLÉMENTS DU MENU HAMBURGER ==========
// On récupère le bouton hamburger et le menu de navigation :D
const hamburger = document.getElementById('hamburger');
const menu = document.getElementById('menu');

// Quand on clique sur le hamburger, on ouvre/ferme le menu ^_^
hamburger.addEventListener('click', () => {
    // Basculer la classe 'active' pour le hamburger et le menu :3
    hamburger.classList.toggle('active');
    menu.classList.toggle('active');
    // Mettre à jour l'attribut aria pour l'accessibilité (important!)
    const isExpanded = menu.classList.contains('active');
    hamburger.setAttribute('aria-expanded', isExpanded.toString());
});

// Fermer le menu si on clique ailleurs sur la page :p
document.addEventListener('click', (e) => {
    // Vérifier si le clic n'est ni sur le hamburger ni sur le menu
    if (!hamburger.contains(e.target) && !menu.contains(e.target)) {
        // Retirer la classe 'active' pour fermer le menu
        hamburger.classList.remove('active');
        menu.classList.remove('active');
        hamburger.setAttribute('aria-expanded', 'false');
    }
});

