// Variables globales pour suivre la liaison et le jour actuels :D
let currentRoute = 'lorient-groix'; // Par défaut on commence avec Lorient-Groix
let currentDay = 1; // On commence au jour 1 du mois

// ========== FONCTIONS POUR OUVRIR ET FERMER LES OVERLAYS ==========
// Fonction pour ouvrir un overlay (popup) ^_^
function openOverlay(overlay) {
    // Ajouter la classe 'active' pour afficher l'overlay
    overlay.classList.add('active');
    // Empêcher le scroll de la page quand l'overlay est ouvert
    document.body.style.overflow = 'hidden';
    
    // Animations trop smooth! Cacher le contenu de fond :3
    if (overlay === overlayTickets) {
        // Faire disparaître le contenu du bas et le header
        document.querySelector('.bottom-content').style.opacity = '0';
        document.querySelector('header').style.opacity = '0';
    }
}

// Fonction pour fermer un overlay (popup) :p
// Fonction pour fermer un overlay (popup) :p
function closeOverlay(overlay) {
    // Retirer la classe 'active' pour masquer l'overlay
    overlay.classList.remove('active');
    // Réactiver le scroll de la page
    document.body.style.overflow = '';
    
    // Montrer le contenu des billets quand on ferme :D
    if (overlay === overlayTickets) {
        // Remettre l'opacité du contenu de fond et du header
        document.querySelector('.bottom-content').style.opacity = '1';
        document.querySelector('header').style.opacity = '1';
        // Réinitialiser la vue des billets quand on ferme l'overlay
        setTimeout(() => {
            // Attendre que l'overlay ne soit plus actif
            if (!overlay.classList.contains('active')) {
                resetTicketsView(); // Tout remettre à zéro!
            }
        }, 300); // Attendre 300ms pour l'animation de fermeture :3
    }
}

// Fonction pour mettre à jour les horaires affichés dans l'overlay disponibilités
function updateSchedule() {
    // Récupérer les horaires pour la liaison et le jour sélectionnés
    const times = schedules[currentRoute][currentDay];
    const container = document.getElementById('scheduleTimes');
    // Créer un bouton pour chaque horaire (trop pratique!)
    container.innerHTML = times.map(time => `<button class="time-slot" type="button">${time}</button>`).join('');
    // Afficher le numéro du jour actuel
    document.getElementById('currentDay').textContent = currentDay;
}

// ========== GESTIONNAIRES D'ÉVÉNEMENTS POUR OUVRIR LES OVERLAYS ==========
// Ouvrir l'overlay "Acheter" quand on clique sur le bouton ^_^
btnAcheter.addEventListener('click', () => openOverlay(overlayAcheter));

// Ouvrir l'overlay "Disponibilités" et mettre à jour les horaires :D
btnDisponibilites.addEventListener('click', () => {
    openOverlay(overlayDisponibilites);
    updateSchedule(); // Important: afficher les bons horaires!
});

// Ouvrir l'overlay "À propos" depuis le menu
menuAbout.addEventListener('click', (e) => {
    e.preventDefault(); // Empêcher le comportement par défaut du lien
    openOverlay(overlayAbout);
    // Fermer le menu hamburger après avoir ouvert l'overlay
    hamburger.classList.remove('active');
    menu.classList.remove('active');
});

// Ouvrir l'overlay "Services" depuis le menu
menuServices.addEventListener('click', (e) => {
    e.preventDefault();
    openOverlay(overlayServices);
    // Fermer le menu hamburger
    hamburger.classList.remove('active');
    menu.classList.remove('active');
});

// Ouvrir l'overlay "Contact" depuis le menu
menuContact.addEventListener('click', (e) => {
    e.preventDefault();
    openOverlay(overlayContact);
    // Fermer le menu hamburger
    hamburger.classList.remove('active');
    menu.classList.remove('active');
});


// Ouvrir l'overlay "Mes Billets" depuis le menu
menuTickets.addEventListener('click', (e) => {
    e.preventDefault();
    openOverlay(overlayTickets);
    // Fermer le menu hamburger
    hamburger.classList.remove('active');
    menu.classList.remove('active');
});

// ========== GESTIONNAIRES D'ÉVÉNEMENTS POUR FERMER LES OVERLAYS ==========
// Fermer les overlays quand on clique sur le bouton X (trop facile!)
closeAcheter.addEventListener('click', () => closeOverlay(overlayAcheter));
closeDisponibilites.addEventListener('click', () => closeOverlay(overlayDisponibilites));
closeAbout.addEventListener('click', () => closeOverlay(overlayAbout));
closeServices.addEventListener('click', () => closeOverlay(overlayServices));
closeContact.addEventListener('click', () => closeOverlay(overlayContact));
closeTickets.addEventListener('click', () => closeOverlay(overlayTickets));

// Fermer les overlays quand on clique sur le fond sombre (backdrop) :3
[overlayAcheter, overlayDisponibilites, overlayAbout, overlayServices, overlayContact, overlayTickets].forEach(overlay => {
    // Pour chaque overlay, ajouter un event listener sur le backdrop
    overlay.querySelector('.overlay-backdrop').addEventListener('click', () => closeOverlay(overlay));
});

// Fermer tous les overlays quand on appuie sur la touche Échap (Escape) :D
document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape') {
        // Fermer tous les overlays d'un coup!
        closeOverlay(overlayAcheter);
        closeOverlay(overlayDisponibilites);
        closeOverlay(overlayAbout);
        closeOverlay(overlayServices);
        closeOverlay(overlayContact);
        closeOverlay(overlayTickets);
    }
});

// ========== GESTION DES BOUTONS DE SÉLECTION DE LIAISON ==========
// Pour chaque bouton de liaison (Lorient-Groix, Groix-Lorient, etc.)
document.querySelectorAll('.route-btn').forEach(btn => {
    btn.addEventListener('click', () => {
        // D'abord, retirer la classe 'active' de tous les boutons
        document.querySelectorAll('.route-btn').forEach(b => {
            b.classList.remove('active');
            b.setAttribute('aria-pressed', 'false'); // Pour l'accessibilité
        });
        // Puis ajouter la classe 'active' au bouton cliqué
        btn.classList.add('active');
        btn.setAttribute('aria-pressed', 'true');
        // Mettre à jour la liaison actuelle (important!)
        currentRoute = btn.dataset.route;
        // Rafraîchir l'affichage des horaires
        updateSchedule();
    });
});

// ========== NAVIGATION ENTRE LES JOURS DU MOIS ==========
// Bouton pour aller au jour précédent (flèche gauche) :p
document.getElementById('prevDay').addEventListener('click', () => {
    // Si on est au jour 1, revenir au jour 30, sinon diminuer de 1
    currentDay = currentDay > 1 ? currentDay - 1 : 30;
    updateSchedule(); // Mettre à jour l'affichage!
});

// Bouton pour aller au jour suivant (flèche droite) :D
document.getElementById('nextDay').addEventListener('click', () => {
    // Si on est au jour 30, revenir au jour 1, sinon augmenter de 1
    currentDay = currentDay < 30 ? currentDay + 1 : 1;
    updateSchedule(); // Mettre à jour l'affichage!
});

// ========== FONCTIONS POUR LA RECHERCHE DE RÉSERVATION ET L'AFFICHAGE DES BILLETS ==========
// L'URL de base de l'API pour récupérer les réservations :3
const API_BASE_URL = 'https://can.iutrs.unistra.fr/api';

// Quand on clique sur le bouton "Rechercher" dans l'overlay des billets
btnSearchReservation.addEventListener('click', (e) => {
    e.preventDefault(); // Empêcher le comportement par défaut du formulaire
    searchReservation(); // Lancer la recherche!
});

// Permettre de lancer la recherche en appuyant sur Entrée dans le champ de texte :D
reservationIdInput.addEventListener('keypress', (e) => {
    if (e.key === 'Enter') { // Si on appuie sur la touche Entrée
        searchReservation(); // Lancer la recherche!
    }
});

// Bouton "Recharger" pour refaire une recherche :3
btnReload.addEventListener('click', () => {
    resetTicketsView(); // Remettre tout à zéro
});

// Bouton "Réessayer" quand il y a une erreur :p
btnRetry.addEventListener('click', () => {
    resetTicketsView(); // Recommencer from scratch!
});

// Fonction pour réinitialiser complètement la vue des billets
function resetTicketsView() {
    // Réafficher le formulaire de saisie
    reservationInputZone.style.display = 'block';
    // Cacher le spinner de chargement
    loadingSpinner.style.display = 'none';
    // Cacher l'affichage des billets
    ticketsDisplay.style.display = 'none';
    // Cacher les messages d'erreur
    // Cacher les messages d'erreur
    errorMessage.style.display = 'none';
    // Vider le champ de saisie
    reservationIdInput.value = '';
    // Remettre le focus sur le champ pour faciliter une nouvelle saisie
    reservationIdInput.focus();
    // Retirer la classe qui cache le titre
    overlayTickets.querySelector('.overlay-content').classList.remove('viewing-tickets');
}

// Fonction asynchrone pour rechercher une réservation dans l'API :3
async function searchReservation() {
    // Récupérer le numéro de réservation saisi et enlever les espaces
    const reservationId = reservationIdInput.value.trim();
    
    // Si le champ est vide, ne rien faire et garder le focus sur le champ
    if (!reservationId) {
        reservationIdInput.focus();
        return; // Sortir de la fonction
    }
    
    // Afficher l'état de chargement :D (spinner qui tourne!)
    reservationInputZone.style.display = 'none'; // Cacher le formulaire
    loadingSpinner.style.display = 'block'; // Montrer le spinner
    ticketsDisplay.style.display = 'none'; // Cacher les billets
    errorMessage.style.display = 'none'; // Cacher les erreurs
    
    try {
        // Obtenir les détails de la réservation depuis l'API :p
        const response = await fetch(`${API_BASE_URL}/reservation/${reservationId}`);
        
        // Si la réservation n'existe pas, throw une erreur
        if (!response.ok) {
            throw new Error('Reservation not found');
        }
        
        // Convertir la réponse en JSON (objet JavaScript)
        const reservationData = await response.json();
        
        // Récupérer les passagers et les véhicules associés à cette réservation :D
        const passagers = []; // Tableau pour stocker tous les passagers
        const vehicules = []; // Tableau pour stocker tous les véhicules
        
        // Boucle pour récupérer chaque passager (1, 2, 3, etc.)
        for (let i = 1; i <= reservationData.nbPassagers; i++) {
            try {
                // Appeler l'API pour ce passager spécifique
                const passengerResponse = await fetch(`${API_BASE_URL}/reservation/${reservationId}/passager/${i}`);
                if (passengerResponse.ok) {
                    // Si la réponse est OK, ajouter le passager au tableau
                    const passenger = await passengerResponse.json();
                    passagers.push(passenger);
                }
            } catch (error) {
                // Si erreur, l'afficher dans la console (pour débugger)
                console.error(`Error fetching passenger ${i}:`, error);
            }
        }
        
        // Même chose pour les véhicules! Boucle pour chaque véhicule :D
        for (let i = 1; i <= reservationData.nbVehicules; i++) {
            try {
                // Appeler l'API pour ce véhicule spécifique
                const vehicleResponse = await fetch(`${API_BASE_URL}/reservation/${reservationId}/vehicule/${i}`);
                if (vehicleResponse.ok) {
                    // Si la réponse est OK, ajouter le véhicule au tableau
                    const vehicle = await vehicleResponse.json();
                    vehicules.push(vehicle);
                }
            } catch (error) {
                // Si erreur, l'afficher dans la console
                console.error(`Error fetching vehicle ${i}:`, error);
            }
        }
        
        // Combiner toutes les données dans un seul objet :D (trop bien organisé!)
        const fullReservation = {
            reservation: reservationData, // Infos de base (date, heure, etc.)
            passagers: passagers, // Liste de tous les passagers
            vehicules: vehicules // Liste de tous les véhicules
        };
        
        // Afficher la réservation complète avec tous les détails!
        displayReservation(fullReservation);
        
    } catch (error) {
        // Si une erreur se produit, afficher l'état d'erreur :c (triste)
        loadingSpinner.style.display = 'none'; // Cacher le spinner
        errorMessage.style.display = 'block'; // Montrer le message d'erreur
        // Personnaliser le message d'erreur
        errorText.textContent = 'Réservation introuvable. Veuillez vérifier votre identifiant.';
        // Logger l'erreur dans la console pour le développeur
        console.error('Error fetching reservation:', error);
    }
}

// ========== FONCTION POUR GÉNÉRER UN QR CODE SVG ==========
// Génère un faux QR code basé sur les données (c'est juste pour le style!) :3
function generateQRCode(data) {
    // Convertir les données en string JSON et prendre les 50 premiers caractères
    const qrData = JSON.stringify(data).substring(0, 50);
    const size = 80; // Taille du QR code en pixels
    const modules = 8; // Nombre de modules (carrés) par côté
    const moduleSize = size / modules; // Taille de chaque carré
    
    // Générer un pattern pseudo-aléatoire basé sur les données
    let seed = 0;
    // Calculer une "seed" en additionnant les codes ASCII des caractères
    for (let i = 0; i < qrData.length; i++) {
        seed += qrData.charCodeAt(i);
    }
    
    // Fonction pour générer un nombre pseudo-aléatoire (entre 0 et 1)
    function pseudoRandom() {
        seed = (seed * 9301 + 49297) % 233280; // Formule mathématique magique!
        return seed / 233280; // Retourner un nombre entre 0 et 1
    }
    
    // Commencer à construire le SVG (image vectorielle)
    let svg = `<svg width="${size}" height="${size}" viewBox="0 0 ${size} ${size}" xmlns="http://www.w3.org/2000/svg">`;
    svg += `<rect width="${size}" height="${size}" fill="white"/>`; // Fond blanc
    
    // Boucle pour créer les modules (carrés noirs ou blancs) du QR code
    for (let y = 0; y < modules; y++) {
        for (let x = 0; x < modules; x++) {
            // Si le nombre aléatoire est > 0.5, créer un carré noir
            if (pseudoRandom() > 0.5) {
                svg += `<rect x="${x * moduleSize}" y="${y * moduleSize}" width="${moduleSize}" height="${moduleSize}" fill="black"/>`;
            }
        }
    }
    
    // Ajouter les "finder patterns" (les gros carrés dans les coins) :D
    const finderSize = moduleSize * 3; // 3x3 modules
    // Trois coins: haut-gauche, haut-droit, bas-gauche
    [[0, 0], [size - finderSize, 0], [0, size - finderSize]].forEach(([x, y]) => {
        // Carré noir extérieur
        svg += `<rect x="${x}" y="${y}" width="${finderSize}" height="${finderSize}" fill="black"/>`;
        // Petit carré blanc intérieur
        svg += `<rect x="${x + moduleSize}" y="${y + moduleSize}" width="${moduleSize}" height="${moduleSize}" fill="white"/>`;
    });
    
    svg += '</svg>'; // Fermer le SVG
    return svg; // Retourner le code SVG complet
}

