// Déclaration des éléments pour le dashboard de remplissage :3
const overlayDashboard = document.getElementById('overlayDashboard');
const closeDashboard = document.getElementById('closeDashboard');
const dashboardContainer = document.getElementById('dashboardContainer');

// Fermer le dashboard avec le bouton X :p
closeDashboard.addEventListener('click', () => closeOverlay(overlayDashboard));

// Fermer le dashboard en cliquant sur le fond sombre
overlayDashboard.querySelector('.overlay-backdrop').addEventListener('click', () => closeOverlay(overlayDashboard));

// Ajouter un événement sur les créneaux horaires pour ouvrir le dashboard :D
// Quand on clique sur un créneau horaire dans "Disponibilités"
document.addEventListener('click', (e) => {
    // Si on clique sur un créneau horaire (classe 'time-slot')
    if (e.target.classList.contains('time-slot')) {
        // Récupérer l'heure du créneau cliqué
        const time = e.target.textContent;
        // Récupérer le jour actuel affiché
        const day = parseInt(document.getElementById('currentDay').textContent);
        // Récupérer la liaison actuelle
        const route = currentRoute;
        // Afficher le dashboard avec ces infos!
        showDashboard(route, day, time);
    }
});

// ========== FONCTION POUR AFFICHER LE DASHBOARD ==========
// Affiche les taux de remplissage pour un créneau horaire :D
async function showDashboard(route, day, time) {
    // Ouvrir le dashboard et fermer les disponibilités
    openOverlay(overlayDashboard);
    closeOverlay(overlayDisponibilites);
    
    // Afficher un spinner pendant le chargement :3
    dashboardContainer.innerHTML = '<div class="loading-spinner"><div class="spinner"></div><p>Chargement...</p></div>';
    
    // Objet qui mappe les routes vers leurs IDs et noms :p
    const liaisons = {
        'lorient-groix': { id: 1, name: 'Lorient → Groix' },
        'groix-lorient': { id: 2, name: 'Groix → Lorient' },
        'quiberon-palais': { id: 3, name: 'Quiberon → Le Palais' },
        'palais-quiberon': { id: 4, name: 'Le Palais → Quiberon' }
    };
    
    // Récupérer les infos de la liaison sélectionnée
    const liaison = liaisons[route];
    // Construire la date au format YYYY-MM-DD (ex: 2025-11-03)
    const date = `2025-11-${day.toString().padStart(2, '0')}`;
    
    try {
        // Appeler l'API pour récupérer les données de remplissage :D
        const response = await fetch(`${API_BASE_URL}/liaison/${liaison.id}/remplissage/${date}`);
        if (!response.ok) throw new Error('Failed to fetch data'); // Si erreur HTTP // Si erreur HTTP
        
        // Convertir la réponse en JSON
        const data = await response.json();
        // Trouver le créneau horaire qui correspond à l'heure cliquée
        const slot = data.find(s => s.heure === time);
        
        // Si pas de données pour ce créneau, afficher un message
        if (!slot) {
            dashboardContainer.innerHTML = '<p style="color: var(--primary); text-align: center;">Aucune donnée disponible</p>';
            return; // Sortir de la fonction
        }
        
        // Calculer les pourcentages de remplissage :3
        const passagerPercent = (slot.nbReservationPassagers / slot.capacitePassagers) * 100;
        const vehiculePercent = (slot.nbReservationVoitures / slot.capaciteVoitures) * 100;
        
        // Déterminer la couleur selon le taux (vert, orange, rouge, jaune) :D
        const passagerColor = getColorClass(passagerPercent);
        const vehiculeColor = getColorClass(vehiculePercent);
        
        dashboardContainer.innerHTML = `
            <header class="dashboard-route-info">
                <h3 class="dashboard-route-title">${liaison.name}</h3>
                <p class="dashboard-date">Date : ${date} | Heure : ${time}</p>
            </header>
            
            <section class="dashboard-slots">
                <article class="dashboard-slot">
                    <h4 class="dashboard-slot-time">Passagers</h4>
                    <div class="dashboard-metrics">
                        <div class="dashboard-metric">
                            <span class="dashboard-metric-label">Taux de remplissage</span>
                            <div class="dashboard-metric-bar">
                                <div class="dashboard-metric-fill ${passagerColor}" style="width: ${Math.min(passagerPercent, 100)}%; padding-left: ${passagerPercent < 5 ? '0.5rem' : '0'}">
                                    ${passagerPercent.toFixed(1)}%
                                </div>
                            </div>
                            <p style="font-family: 'Lato', sans-serif; font-size: 0.9rem; color: rgba(255,255,255,0.6); margin-top: 0.5rem;">
                                ${slot.nbReservationPassagers} / ${slot.capacitePassagers} passagers
                            </p>
                        </div>
                    </div>
                </article>
                
                <article class="dashboard-slot">
                    <h4 class="dashboard-slot-time">Véhicules</h4>
                    <div class="dashboard-metrics">
                        <div class="dashboard-metric">
                            <span class="dashboard-metric-label">Taux de remplissage</span>
                            <div class="dashboard-metric-bar">
                                <div class="dashboard-metric-fill ${vehiculeColor}" style="width: ${Math.min(vehiculePercent, 100)}%; padding-left: ${vehiculePercent < 5 ? '0.5rem' : '0'}">
                                    ${vehiculePercent.toFixed(1)}%
                                </div>
                            </div>
                            <p style="font-family: 'Lato', sans-serif; font-size: 0.9rem; color: rgba(255,255,255,0.6); margin-top: 0.5rem;">
                                ${slot.nbReservationVoitures} / ${slot.capaciteVoitures} voitures
                            </p>
                        </div>
                    </div>
                </article>
            </section>
        `;
        
    } catch (error) {
        // En cas d'erreur, afficher un message d'erreur :c
        console.error('Error fetching dashboard data:', error);
        dashboardContainer.innerHTML = '<p style="color: #e74c3c; text-align: center;">Erreur de chargement des données</p>';
    }
}

// Fonction pour déterminer la couleur selon le pourcentage :3
function getColorClass(percent) {
    if (percent > 100) return 'fill-yellow'; // Surbooking! (jaune fluo)
    if (percent >= 75) return 'fill-red'; // Presque plein (rouge)
    if (percent >= 50) return 'fill-orange'; // À moitié plein (orange)
    return 'fill-green'; // Beaucoup de place (vert)
}

// ========== SECTION STATISTIQUES (STATISTICS) ==========
// Déclaration des éléments pour les statistiques (protégé par mot de passe!) :D
const overlayStats = document.getElementById('overlayStats');
const closeStats = document.getElementById('closeStats');
const menuStats = document.getElementById('menuStats');
const statsLogin = document.getElementById('statsLogin');
const statsLoginForm = document.getElementById('statsLoginForm');
const statsPassword = document.getElementById('statsPassword');
const statsLoginError = document.getElementById('statsLoginError');
const statsDisplay = document.getElementById('statsDisplay');
const statsSpinner = document.getElementById('statsSpinner');
const statsContainer = document.getElementById('statsContainer');

// Mot de passe pour accéder aux stats (super sécurisé lol) :p
const STATS_PASSWORD = 'admin';

// Ouvrir l'overlay stats depuis le menu (si visible)
menuStats.addEventListener('click', (e) => {
    e.preventDefault();
    openOverlay(overlayStats);
    hamburger.classList.remove('active');
    menu.classList.remove('active');
});

// Fermer l'overlay stats avec le bouton X :3
closeStats.addEventListener('click', () => {
    closeOverlay(overlayStats); // Fermer
    statsLogin.style.display = 'block'; // Réafficher le login
    statsDisplay.style.display = 'none'; // Cacher les stats
    statsPassword.value = ''; // Vider le mot de passe
    statsLoginError.style.display = 'none'; // Cacher l'erreur
});

// Fermer en cliquant sur le fond sombre
overlayStats.querySelector('.overlay-backdrop').addEventListener('click', () => {
    closeOverlay(overlayStats);
    statsLogin.style.display = 'block';
    statsDisplay.style.display = 'none';
    statsPassword.value = '';
    statsLoginError.style.display = 'none';
});

// Quand on soumet le formulaire de connexion aux stats :D
statsLoginForm.addEventListener('submit', (e) => {
    e.preventDefault(); // Empêcher le rechargement de la page
    const password = statsPassword.value; // Récupérer le mot de passe saisi
    
    // Si le mot de passe est correct
    if (password === STATS_PASSWORD) {
        statsLogin.style.display = 'none'; // Cacher le formulaire de login
        statsDisplay.style.display = 'block'; // Afficher les stats
        statsLoginError.style.display = 'none'; // Cacher l'erreur
        menuStats.style.display = 'block'; // Rendre le menu stats visible
        loadStatistics(); // Charger les statistiques!
    } else {
        // Si le mot de passe est incorrect :c
        statsLoginError.style.display = 'block'; // Afficher l'erreur
        statsPassword.value = ''; // Vider le champ
    }
});

// ========== FONCTION POUR CHARGER LES STATISTIQUES ==========
// Récupère et affiche le chiffre d'affaires de toutes les liaisons :D
async function loadStatistics() {
    // Vider le container et afficher le spinner
    statsContainer.innerHTML = '';
    statsSpinner.style.display = 'block';
    
    try {
        // Liste de toutes les liaisons à interroger :3
        const liaisons = [
            { id: 1, name: 'Lorient → Groix' },
            { id: 2, name: 'Groix → Lorient' },
            { id: 3, name: 'Quiberon → Le Palais' },
            { id: 4, name: 'Le Palais → Quiberon' }
        ];
        
        // Variable pour le chiffre d'affaires total
        let totalRevenue = 0;
        // Variable pour stocker le HTML de toutes les cartes de liaisons
        let routesHTML = '';
        
        // Boucle sur chaque liaison pour récupérer ses stats :p
        for (const liaison of liaisons) {
            // Appeler l'API pour le chiffre d'affaires de cette liaison
            const response = await fetch(`${API_BASE_URL}/liaison/${liaison.id}/chiffreAffaire`);
            if (!response.ok) continue; // Si erreur, passer à la suivante // Si erreur, passer à la suivante
            
            // Convertir la réponse en JSON
            const data = await response.json();
            
            // Extraire les chiffres d'affaires passagers et véhicules :D
            const passagerRevenue = data.passagers.chiffreAffaire || 0;
            const vehiculeRevenue = data.vehicules.chiffreAffaire || 0;
            // Calculer le total pour cette liaison
            const routeTotal = passagerRevenue + vehiculeRevenue;
            // Ajouter au total global
            totalRevenue += routeTotal;
            
            routesHTML += `
                <div class="stats-route-card">
                    <h3 class="stats-route-name">${liaison.name}</h3>
                    <div class="stats-route-data">
                        <div class="stats-data-item">
                            <span class="stats-data-label">CA Passagers</span>
                            <span class="stats-data-value revenue">${passagerRevenue.toFixed(2)} €</span>
                        </div>
                        <div class="stats-data-item">
                            <span class="stats-data-label">Nombre passagers</span>
                            <span class="stats-data-value">${data.passagers.nombre}</span>
                        </div>
                        <div class="stats-data-item">
                            <span class="stats-data-label">CA Véhicules</span>
                            <span class="stats-data-value revenue">${vehiculeRevenue.toFixed(2)} €</span>
                        </div>
                        <div class="stats-data-item">
                            <span class="stats-data-label">Quantité véhicules</span>
                            <span class="stats-data-value">${data.vehicules.quantite}</span>
                        </div>
                        <div class="stats-data-item" style="border-top: 2px solid rgba(255,255,255,0.2); padding-top: 0.75rem; margin-top: 0.5rem;">
                            <span class="stats-data-label">Total liaison</span>
                            <span class="stats-data-value revenue">${routeTotal.toFixed(2)} €</span>
                        </div>
                    </div>
                </div>
            `;
        }
        
        // Cacher le spinner et afficher les résultats! :3
        statsSpinner.style.display = 'none';
        // Construire le HTML avec le total global et toutes les cartes
        statsContainer.innerHTML = `
            <section class="stats-global">
                <h3>Chiffre d'affaires global - Novembre 2025</h3>
                <p class="stats-global-value">${totalRevenue.toFixed(2)} €</p>
            </section>
            <section class="stats-routes">
                ${routesHTML}
            </section>
        `;
        
    } catch (error) {
        // En cas d'erreur, afficher un message :c
        console.error('Error loading statistics:', error);
        statsSpinner.style.display = 'none'; // Cacher le spinner
        // Afficher un message d'erreur à l'utilisateur
        statsContainer.innerHTML = '<p style="color: #e74c3c; text-align: center;">Erreur de chargement des statistiques</p>';
    }
}